   77 // D8: received�� �ڷ� ���� �ʰ�, �̺�Ʈ�� REPORT_EVERY���� �ִ� 1ȸ
   78 struct Progress<F> {
   79     received: AtomicU64,
   80     total: Option<u64>,
   81     mode: DownloadMode,
   82     last: Mutex<(u64, Instant)>,
   83     cb: F,
   84 }
   85 
   86 impl<F: Fn(DownloadProgress)> Progress<F> {
   87     fn new(start: u64, total: Option<u64>, mode: DownloadMode, cb: F) -> Self {
   88         Progress { received: AtomicU64::new(start), total, mode, last: Mutex::new((start, Instant::now())), cb }
   89     }
   90     fn emit(&self, force: bool) {
   91         let mut last = self.last.lock().unwrap();
   92         if !force && last.1.elapsed() < REPORT_EVERY {
   93             return;
   94         }
   95         let mut v = self.received.load(Ordering::SeqCst).max(last.0);
   96         if let Some(t) = self.total {
   97             v = v.min(t);
   98         }
   99         *last = (v, Instant::now());
  100         (self.cb)(DownloadProgress { received: v, total: self.total, mode: self.mode });
  101     }
  102     fn add(&self, n: u64) {
  103         self.received.fetch_add(n, Ordering::SeqCst);
  104         self.emit(false);
  105     }
  106     fn undo(&self, n: u64) {
  107         self.received.fetch_sub(n, Ordering::SeqCst); // ��õ� �� �ٽ� ����
  108     }
  109     fn finish(&self) {
  110         let total = self.total.unwrap_or(self.received.load(Ordering::SeqCst).max(self.last.lock().unwrap().0));
  111         (self.cb)(DownloadProgress { received: total, total: Some(total), mode: self.mode });
  112     }
  113 }
