  171 pub async fn download<F: Fn(DownloadProgress) + Send + Sync + 'static>(
  172     request: DownloadRequest,
  173     cancel: Arc<AtomicBool>,
  174     on_progress: F,
  175 ) -> Result<Option<PathBuf>, String> {
  176     if cancel.load(Ordering::SeqCst) {
  177         return Ok(None);
  178     }
  179     let client = client(&request)?;
  180     // D2: Range 0-0 Ž�� ��û
  181     let probe = retry(|| async { client.get(&request.url).header(RANGE, "bytes=0-0").send().await.map_err(net) }).await?;
  182     let status = probe.status().as_u16();
  183     match (status, content_range(&probe)) {
  184         (206, Some((0, _, Some(total)))) => segmented(client, request, total, cancel, on_progress).await,
  185         (200, _) => single(&client, &request, Some(probe), cancel, on_progress).await,
  186         (206, _) | (416, _) => single(&client, &request, None, cancel, on_progress).await,
  187         _ => Err(format!("������ ������ �����߽��ϴ� (HTTP {status})")),
  188     }
  189 }
