  244 struct Job<F> {
  245     client: Client,
  246     url: String,
  247     part: PathBuf,
  248     map: PathBuf,
  249     total: u64,
  250     pending: Vec<u64>, // ���� �� ���� ���� ��ȣ
  251     next: AtomicUsize,
  252     stop: AtomicBool,
  253     cancel: Arc<AtomicBool>,
  254     progress: Progress<F>,
  255 }
  256 
  257 impl<F: Fn(DownloadProgress)> Job<F> {
  258     fn span(&self, i: u64) -> (u64, u64) {
  259         (i * CHUNK, ((i + 1) * CHUNK).min(self.total) - 1)
  260     }
  261 
  262     // ���� �ϳ��� ��°�� �޾� �����Ѵ�. ��ҵǸ� None
  263     async fn fetch(&self, i: u64) -> Result<Option<Vec<u8>>, String> {
  264         let (a, b) = self.span(i);
  265         let want = b - a + 1;
  266         let mut resp = self.client.get(&self.url).header(RANGE, format!("bytes={a}-{b}")).send().await.map_err(net)?;
  267         if resp.status().as_u16() != 206 || content_range(&resp) != Some((a, b, Some(self.total))) {
  268             return Err("������ ��û�� ������ �ٸ� ������ ���½��ϴ�".to_string()); // D5
  269         }
  270         let mut buf = Vec::with_capacity(want as usize);
  271         let mut failed = None;
  272         while failed.is_none() {
  273             match resp.chunk().await {
  274                 Ok(Some(chunk)) => {
  275                     if self.cancel.load(Ordering::SeqCst) {
  276                         self.progress.undo(buf.len() as u64);
  277                         return Ok(None);
  278                     }
  279                     self.progress.add(chunk.len() as u64);
  280                     buf.extend_from_slice(&chunk);
  281                     if buf.len() as u64 > want {
  282                         break;
  283                     }
  284                 }
  285                 Ok(None) => break,
  286                 Err(e) => failed = Some(net(e)),
  287             }
  288         }
  289         if failed.is_some() || buf.len() as u64 != want {
  290             self.progress.undo(buf.len() as u64);
  291             return Err(failed.unwrap_or_else(|| "���� ������ ���̰� ���� �ʽ��ϴ�".to_string())); // D5
  292         }
  293         Ok(Some(buf))
  294     }
  295 
  296     // ������ ���� flush�� �ڿ��� map�� �Ϸ� ǥ�ø� �Ѵ�
  297     async fn store(&self, i: u64, data: &[u8]) -> Result<(), String> {
  298         for (path, at, bytes) in [(&self.part, self.span(i).0, data), (&self.map, 8 + i, &[1u8][..])] {
  299             let mut f = OpenOptions::new().write(true).open(path).await.map_err(io)?;
  300             f.seek(SeekFrom::Start(at)).await.map_err(io)?;
  301             f.write_all(bytes).await.map_err(io)?;
  302             f.flush().await.map_err(io)?;
  303         }
  304         Ok(())
  305     }
  306 
  307     async fn worker(&self) -> Result<(), String> {
  308         loop {
  309             let n = self.next.fetch_add(1, Ordering::SeqCst);
  310             if n >= self.pending.len() || self.stop.load(Ordering::SeqCst) || self.cancel.load(Ordering::SeqCst) {
  311                 return Ok(());
  312             }
  313             let i = self.pending[n];
  314             let stored = match retry(|| self.fetch(i)).await {
  315                 Ok(Some(data)) => self.store(i, &data).await,
  316                 Ok(None) => return Ok(()),
  317                 Err(e) => Err(e),
  318             };
  319             if stored.is_err() {
  320                 self.stop.store(true, Ordering::SeqCst);
  321                 return stored;
  322             }
  323         }
  324     }
  325 }
  326 
  327 // D4/D5: ���� �� ���� ���� �ƴϸ�(ũ�� ����ġ, ���� �̻�, 0/1 �ƴ� ��) ������ ó������
  328 async fn load_state(part: &Path, map: &Path, total: u64, n: u64) -> Result<Vec<u8>, String> {
  329     if let (Ok(m), Ok(meta)) = (tokio::fs::read(map).await, tokio::fs::metadata(part).await) {
  330         if m.len() as u64 == 8 + n && m[..8] == total.to_le_bytes() && m[8..].iter().all(|&b| b <= 1) && meta.len() == total {
  331             return Ok(m[8..].to_vec());
  332         }
  333     }
  334     File::create(part).await.map_err(io)?.set_len(total).await.map_err(io)?;
  335     let mut m = total.to_le_bytes().to_vec();
  336     m.resize(8 + n as usize, 0);
  337     tokio::fs::write(map, m).await.map_err(io)?;
  338     Ok(vec![0; n as usize])
  339 }
  340 
  341 async fn segmented<F: Fn(DownloadProgress) + Send + Sync + 'static>(
  342     client: Client,
  343     req: DownloadRequest,
  344     total: u64,
  345     cancel: Arc<AtomicBool>,
  346     on_progress: F,
  347 ) -> Result<Option<PathBuf>, String> {
  348     let (part, map) = (side(&req.destination, ".part"), side(&req.destination, ".map"));
  349     let n = total.div_ceil(CHUNK);
  350     let done = load_state(&part, &map, total, n).await?;
  351     let pending: Vec<u64> = (0..n).filter(|&i| done[i as usize] == 0).collect();
  352     let have = total - pending.iter().map(|&i| ((i + 1) * CHUNK).min(total) - i * CHUNK).sum::<u64>();
  353     let job = Arc::new(Job {
  354         client,
  355         url: req.url,
  356         part: part.clone(),
  357         map: map.clone(),
  358         total,
  359         next: AtomicUsize::new(0),
  360         pending,
  361         stop: AtomicBool::new(false),
  362         cancel: cancel.clone(),
  363         progress: Progress::new(have, Some(total), DownloadMode::Segmented, on_progress),
  364     });
  365     job.progress.emit(true);
  366     let workers: Vec<_> = (0..CONNECTIONS.min(job.pending.len()))
  367         .map(|_| {
  368             let job = job.clone();
  369             tokio::spawn(async move { job.worker().await })
  370         })
  371         .collect();
  372     let mut failure = None;
  373     for w in workers {
  374         match w.await {
  375             Ok(Ok(())) => {}
  376             Ok(Err(e)) => failure = failure.or(Some(e)),
  377             Err(e) => failure = failure.or(Some(format!("���� �۾� ����: {e}"))),
  378         }
  379     }
  380     if let Some(e) = failure {
  381         return Err(e);
  382     }
  383     if cancel.load(Ordering::SeqCst) {
  384         return Ok(None);
  385     }
  386     job.progress.finish();
  387     tokio::fs::rename(&part, &req.destination).await.map_err(io)?; // D1: �ϼ� �Ŀ��� ��Ÿ����
  388     let _ = tokio::fs::remove_file(&map).await;
  389     Ok(Some(req.destination))
  390 }
