  456                                 let t = if o.unknown { "*".to_string() } else { total.to_string() };
  457                                 ("206 Partial Content", a, b + 1, format!("Content-Range: bytes {shown}-{b}/{t}\r\n"))
  458                             }
  459                             _ => ("200 OK", 0, total, String::new()),
  460                         };
  461                         let mut body = data[a..b].to_vec();
  462                         if o.over && !cr.is_empty() && !probe {
  463                             body.push(7);
  464                         }
  465                         let mut r = format!("HTTP/1.1 {status}\r\nContent-Length: {}\r\n{cr}Connection: close\r\n\r\n", body.len()).into_bytes();
  466                         if !probe && o.drop_first > 0 {
  467                             let mut g = opt.lock().unwrap();
  468                             if g.drop_first > 0 {
  469                                 g.drop_first -= 1;
  470                                 body.truncate(100);
  471                             }
  472                         }
  473                         r.extend(body);
  474                         r
  475                     };
  476                     let head_len = resp.windows(4).position(|w| w == b"\r\n\r\n").unwrap() + 4;
  477                     let _ = st.write_all(&resp[..head_len]);
  478                     let n_chunks = resp[head_len..].chunks(64 * 1024).count();
  479                     for (k, c) in resp[head_len..].chunks(64 * 1024).enumerate() {
  480                         if st.write_all(c).is_err() {
  481                             break;
  482                         }
  483                         served.fetch_add(c.len() as u64, Ordering::SeqCst);
  484                         if k + 1 < n_chunks {
  485                             std::thread::sleep(Duration::from_millis(delay.load(Ordering::SeqCst)));
  486                         }
  487                     }
  488                     active.fetch_sub(1, Ordering::SeqCst);
  489                 });
  490             }
  491         });
  492         s
  493     }
