28:/// 토큰에 대한 취소 플래그를 만들어 등록하고 돌려준다.
29:pub fn register_cancel(token: &str) -> Arc<AtomicBool> {
30:    let flag = Arc::new(AtomicBool::new(false));
31:    if let Ok(mut map) = CANCELLERS.lock() {
32:        map.insert(token.to_string(), flag.clone());
33:    }
34:    flag
