38:pub fn request_cancel(token: &str) -> bool {
39:    if let Ok(map) = CANCELLERS.lock() {
40:        if let Some(flag) = map.get(token) {
41:            flag.store(true, Ordering::SeqCst);
42:            return true;
43:        }
