96:struct ProgressEmitter {
97:    received: Arc<AtomicU64>,
98:    total: Option<u64>,
99:    mode: DownloadMode,
100:    last_emit_ms: AtomicU64,
101:    started: Instant,
102:    callback: Arc<dyn Fn(DownloadProgress) + Send + Sync>,
103:}
104:
105:impl ProgressEmitter {
106:    fn new(
107:        received: Arc<AtomicU64>,
108:        total: Option<u64>,
109:        mode: DownloadMode,
110:        callback: Arc<dyn Fn(DownloadProgress) + Send + Sync>,
111:    ) -> Self {
112:        Self {
113:            received,
114:            total,
115:            mode,
116:            last_emit_ms: AtomicU64::new(0),
117:            started: Instant::now(),
118:            callback,
119:        }
120:    }
121:
122:    fn emit_if_due(&self) {
123:        let elapsed = self.started.elapsed().as_millis().min(u64::MAX as u128) as u64;
124:        let last = self.last_emit_ms.load(Ordering::Relaxed);
125:        if elapsed.saturating_sub(last) < PROGRESS_EMIT_INTERVAL.as_millis() as u64 {
126:            return;
127:        }
128:        if self
129:            .last_emit_ms
130:            .compare_exchange(last, elapsed, Ordering::Relaxed, Ordering::Relaxed)
131:            .is_ok()
132:        {
133:            self.emit();
134:        }
135:    }
136:
137:    fn emit(&self) {
138:        (self.callback)(DownloadProgress {
139:            received: self.received.load(Ordering::Relaxed),
140:            total: self.total,
141:            mode: self.mode,
142:        });
143:    }
144:}
