146:fn client() -> Result<Client, String> {
147:    Client::builder()
148:        .connect_timeout(Duration::from_secs(20))
149:        .redirect(reqwest::redirect::Policy::limited(10))
150:        .user_agent(USER_AGENT)
151:        .build()
152:        .map_err(|e| format!("HTTP 클라이언트 생성 실패: {e}"))
153:}
