155:fn request(
156:    client: &Client,
157:    method: reqwest::Method,
158:    request: &DownloadRequest,
159:) -> reqwest::RequestBuilder {
160:    let mut builder = client
161:        .request(method, &request.url)
162:        // 압축된 응답은 바이트 오프셋과 실제 파일 오프셋을 다르게 만들 수 있다.
163:        .header(ACCEPT_ENCODING, "identity");
164:    if let Some(cookie) = request.cookie_header.as_deref().filter(|v| !v.is_empty()) {
165:        builder = builder.header(COOKIE, cookie);
166:    }
167:    if let Some(referer) = request.referer.as_deref().filter(|v| !v.is_empty()) {
168:        builder = builder.header(REFERER, referer);
169:    }
170:    builder
171:}
