173:fn parse_content_range(value: &str) -> Option<u64> {
174:    // `bytes 0-0/4722087959`; 크기를 모르는 `bytes 0-0/*`는 거부한다.
175:    let (_, total) = value.rsplit_once('/')?;
176:    total.parse::<u64>().ok().filter(|n| *n > 0)
177:}
