179:async fn probe_range(
180:    client: &Client,
181:    request_info: &DownloadRequest,
182:) -> Result<(bool, Option<u64>), String> {
183:    let response = request(client, reqwest::Method::GET, request_info)
184:        .header(RANGE, "bytes=0-0")
185:        .send()
186:        .await
187:        .map_err(|e| format!("다운로드 서버 연결 실패: {e}"))?;
188:
189:    if response.status() == StatusCode::PARTIAL_CONTENT {
190:        let total = response
191:            .headers()
192:            .get(CONTENT_RANGE)
