235:fn segment_bounds(total: u64, count: usize, index: usize) -> (u64, u64) {
236:    let count = count.max(1) as u64;
237:    let index = index as u64;
238:    let base = total / count;
239:    let remainder = total % count;
240:    // 나머지 바이트를 앞쪽 구간에 하나씩 배분하면 모든 구간이 빈틈·중복 없이 이어진다.
241:    let start = index * base + index.min(remainder);
242:    let size = base + u64::from(index < remainder);
243:    let end = start.saturating_add(size).saturating_sub(1);
244:    (start, end)
245:}
