247:async fn prepare_resume(
248:    destination: &Path,
249:    total: u64,
250:    segment_count: usize,
251:) -> Result<(PathBuf, PathBuf, PathBuf, Vec<u64>), String> {
252:    let part_path = sidecar_path(destination, "download");
253:    let meta_path = sidecar_path(destination, "download.json");
254:    let state_path = sidecar_path(destination, "download.state");
255:    let expected = ResumeMeta {
256:        version: 1,
257:        total,
258:        segment_count,
259:    };
260:
261:    let existing_meta = tokio::fs::read_to_string(&meta_path)
262:        .await
263:        .ok()
264:        .and_then(|s| serde_json::from_str::<ResumeMeta>(&s).ok());
265:    let reusable = existing_meta
266:        .as_ref()
267:        .is_some_and(|m| m.version == 1 && m.total == total && m.segment_count == segment_count)
268:        && tokio::fs::metadata(&part_path)
269:            .await
270:            .is_ok_and(|m| m.len() == total);
271:
272:    if !reusable {
273:        for path in [&part_path, &meta_path, &state_path] {
274:            if let Err(e) = tokio::fs::remove_file(path).await {
275:                if e.kind() != std::io::ErrorKind::NotFound {
276:                    return Err(format!("이전 임시 파일 정리 실패({}): {e}", path.display()));
277:                }
278:            }
279:        }
280:        let file = tokio::fs::File::create(&part_path)
281:            .await
282:            .map_err(|e| format!("임시 파일 생성 실패({}): {e}", part_path.display()))?;
283:        file.set_len(total)
284:            .await
285:            .map_err(|e| format!("임시 파일 크기 설정 실패: {e}"))?;
286:        tokio::fs::write(
287:            &meta_path,
288:            serde_json::to_vec(&expected).map_err(|e| format!("재개 정보 생성 실패: {e}"))?,
289:        )
290:        .await
291:        .map_err(|e| format!("재개 정보 저장 실패: {e}"))?;
292:        tokio::fs::write(&state_path, vec![0u8; segment_count * 8])
293:            .await
294:            .map_err(|e| format!("구간 상태 생성 실패: {e}"))?;
295:    }
296:
297:    let raw_state = tokio::fs::read(&state_path).await.unwrap_or_default();
298:    let mut offsets = Vec::with_capacity(segment_count);
299:    for index in 0..segment_count {
300:        let pos = index * 8;
301:        let value = raw_state
302:            .get(pos..pos + 8)
303:            .and_then(|bytes| bytes.try_into().ok())
304:            .map(u64::from_le_bytes)
305:            .unwrap_or(0);
306:        let (start, end) = segment_bounds(total, segment_count, index);
307:        let segment_len = end.saturating_sub(start).saturating_add(1);
308:        offsets.push(valid_resume_offset(value, segment_len));
309:    }
310:    Ok((part_path, meta_path, state_path, offsets))
311:}
