313:async fn download_segment(
314:    client: &Client,
315:    request_info: &DownloadRequest,
316:    part_path: &Path,
317:    state_file: Arc<Mutex<tokio::fs::File>>,
318:    progress: Arc<ProgressEmitter>,
319:    cancel: Arc<AtomicBool>,
320:    segment_count: usize,
321:    index: usize,
322:    initial_offset: u64,
323:) -> Result<(), String> {
324:    let total = progress
325:        .total
326:        .expect("분할 다운로드는 전체 크기가 필요하다");
327:    let (segment_start, segment_end) = segment_bounds(total, segment_count, index);
328:    let segment_len = segment_end.saturating_sub(segment_start).saturating_add(1);
329:    if initial_offset >= segment_len {
330:        return Ok(());
331:    }
332:
333:    let mut completed = initial_offset;
334:    let mut checkpointed = initial_offset;
335:    for attempt in 0..MAX_RETRIES {
336:        if cancelled(&cancel) {
337:            return Err(CANCEL_SENTINEL.to_string());
338:        }
339:        let start = segment_start + completed;
340:        let mut response = match request(client, reqwest::Method::GET, request_info)
341:            .header(RANGE, format!("bytes={start}-{segment_end}"))
342:            .send()
343:            .await
344:        {
345:            Ok(response) if response.status() == StatusCode::PARTIAL_CONTENT => response,
346:            Ok(response) => {
347:                return Err(format!(
348:                    "Range 응답이 아닙니다(구간 {index}, HTTP {})",
349:                    response.status()
350:                ))
351:            }
352:            Err(e) if attempt + 1 < MAX_RETRIES => {
353:                tokio::time::sleep(Duration::from_millis(500 * (attempt as u64 + 1))).await;
354:                eprintln!("[segmented-download] 구간 {index} 재시도: {e}");
355:                continue;
356:            }
357:            Err(e) => return Err(format!("구간 {index} 다운로드 실패: {e}")),
358:        };
359:        let expected_range_prefix = format!("bytes {start}-");
360:        let valid_range = response
361:            .headers()
362:            .get(CONTENT_RANGE)
363:            .and_then(|value| value.to_str().ok())
364:            .is_some_and(|value| value.starts_with(&expected_range_prefix));
365:        if !valid_range {
366:            return Err(format!(
367:                "구간 {index}의 Content-Range가 요청 범위와 다릅니다"
368:            ));
369:        }
370:
371:        let mut file = tokio::fs::OpenOptions::new()
372:            .write(true)
373:            .open(part_path)
374:            .await
375:            .map_err(|e| format!("임시 파일 열기 실패: {e}"))?;
376:        file.seek(std::io::SeekFrom::Start(start))
377:            .await
378:            .map_err(|e| format!("구간 {index} seek 실패: {e}"))?;
379:
380:        let transfer = async {
381:            while let Some(chunk) = response
382:                .chunk()
383:                .await
384:                .map_err(|e| format!("구간 {index} 수신 실패: {e}"))?
385:            {
386:                if cancelled(&cancel) {
387:                    return Err(CANCEL_SENTINEL.to_string());
388:                }
389:                let remaining = segment_len.saturating_sub(completed);
390:                if chunk.len() as u64 > remaining {
391:                    return Err(format!("구간 {index}이 예정 크기를 초과했습니다"));
392:                }
393:                file.write_all(&chunk)
394:                    .await
395:                    .map_err(|e| format!("구간 {index} 쓰기 실패: {e}"))?;
396:                completed += chunk.len() as u64;
397:                progress
398:                    .received
399:                    .fetch_add(chunk.len() as u64, Ordering::Relaxed);
400:                progress.emit_if_due();
401:
402:                if completed.saturating_sub(checkpointed) >= RESUME_CHECKPOINT_BYTES
403:                    || completed == segment_len
404:                {
405:                    let mut state = state_file.lock().await;
406:                    state
407:                        .seek(std::io::SeekFrom::Start((index * 8) as u64))
408:                        .await
409:                        .map_err(|e| format!("구간 상태 seek 실패: {e}"))?;
410:                    state
411:                        .write_all(&completed.to_le_bytes())
412:                        .await
413:                        .map_err(|e| format!("구간 상태 저장 실패: {e}"))?;
414:                    checkpointed = completed;
415:                }
416:            }
417:            file.flush()
418:                .await
419:                .map_err(|e| format!("구간 {index} flush 실패: {e}"))?;
420:            Ok::<(), String>(())
421:        }
422:        .await;
423:
424:        match transfer {
425:            Ok(()) if completed == segment_len => return Ok(()),
426:            Ok(()) if attempt + 1 < MAX_RETRIES => {
427:                tokio::time::sleep(Duration::from_millis(500 * (attempt as u64 + 1))).await;
428:            }
429:            Ok(()) => {
430:                return Err(format!(
431:                    "구간 {index} 크기 불일치: {completed}/{segment_len} bytes"
432:                ))
433:            }
434:            // 취소는 재시도하지 않고 즉시 올린다.
435:            Err(e) if e == CANCEL_SENTINEL => return Err(e),
436:            Err(e) if attempt + 1 < MAX_RETRIES => {
437:                tokio::time::sleep(Duration::from_millis(500 * (attempt as u64 + 1))).await;
438:                eprintln!("[segmented-download] 구간 {index} 재시도: {e}");
439:            }
440:            Err(e) => return Err(e),
441:        }
442:    }
443:    Err(format!("구간 {index} 재시도 횟수 초과"))
444:}
