446:async fn segmented<F>(
447:    client: Client,
448:    request_info: DownloadRequest,
449:    total: u64,
450:    cancel: Arc<AtomicBool>,
451:    callback: Arc<F>,
452:) -> Result<PathBuf, String>
453:where
454:    F: Fn(DownloadProgress) + Send + Sync + 'static,
455:{
456:    let segment_count = (CONNECTIONS * SEGMENTS_PER_CONNECTION)
457:        .min(usize::try_from(total.max(1)).unwrap_or(usize::MAX))
458:        .max(1);
459:    let (part_path, meta_path, state_path, offsets) =
460:        prepare_resume(&request_info.destination, total, segment_count).await?;
461:    let resumed = offsets.iter().copied().sum::<u64>().min(total);
462:    let received = Arc::new(AtomicU64::new(resumed));
463:    let callback: Arc<dyn Fn(DownloadProgress) + Send + Sync> = callback;
464:    let progress = Arc::new(ProgressEmitter::new(
465:        received,
466:        Some(total),
467:        DownloadMode::Segmented,
468:        callback,
469:    ));
470:    progress.emit();
471:
472:    let state_file = Arc::new(Mutex::new(
473:        tokio::fs::OpenOptions::new()
474:            .read(true)
475:            .write(true)
476:            .open(&state_path)
477:            .await
478:            .map_err(|e| format!("구간 상태 열기 실패: {e}"))?,
479:    ));
480:    let next = Arc::new(AtomicUsize::new(0));
481:    let offsets = Arc::new(offsets);
482:    let mut workers = JoinSet::new();
483:
484:    for _ in 0..CONNECTIONS.min(segment_count) {
485:        let client = client.clone();
486:        let request_info = request_info.clone();
487:        let part_path = part_path.clone();
488:        let state_file = state_file.clone();
489:        let progress = progress.clone();
490:        let next = next.clone();
491:        let offsets = offsets.clone();
492:        let cancel = cancel.clone();
493:        workers.spawn(async move {
494:            loop {
495:                if cancelled(&cancel) {
496:                    return Err::<(), String>(CANCEL_SENTINEL.to_string());
497:                }
498:                let index = next.fetch_add(1, Ordering::Relaxed);
499:                if index >= segment_count {
500:                    return Ok::<(), String>(());
501:                }
502:                download_segment(
503:                    &client,
504:                    &request_info,
505:                    &part_path,
506:                    state_file.clone(),
507:                    progress.clone(),
508:                    cancel.clone(),
509:                    segment_count,
510:                    index,
511:                    offsets[index],
512:                )
513:                .await?;
514:            }
515:        });
516:    }
517:
518:    while let Some(result) = workers.join_next().await {
519:        let joined = result.map_err(|e| format!("다운로드 작업 실행 실패: {e}"))?;
520:        if let Err(e) = joined {
521:            // 취소 sentinel은 감싸지 않고 그대로 올려 `download`가 Ok(None)으로 바꾸게 한다.
522:            if e == CANCEL_SENTINEL {
523:                return Err(CANCEL_SENTINEL.to_string());
524:            }
525:            return Err(format!("분할 다운로드 실패: {e}"));
526:        }
527:    }
528:
529:    progress.received.store(total, Ordering::Relaxed);
530:    progress.emit();
531:    tokio::fs::rename(&part_path, &request_info.destination)
532:        .await
533:        .map_err(|e| {
534:            format!(
535:                "완료 파일 이동 실패({}): {e}",
536:                request_info.destination.display()
537:            )
538:        })?;
539:    let _ = tokio::fs::remove_file(meta_path).await;
540:    let _ = tokio::fs::remove_file(state_path).await;
541:    Ok(request_info.destination)
542:}
