602:/// 최종 URL을 받아 파일을 전송한다. `Ok(Some(path))` 성공, `Ok(None)` 취소, `Err` 실패.
603:/// 취소 시 sidecar를 남겨 다음 실행에서 재개할 수 있게 한다.
604:pub async fn download<F>(
605:    request_info: DownloadRequest,
606:    cancel: Arc<AtomicBool>,
607:    on_progress: F,
608:) -> Result<Option<PathBuf>, String>
609:where
610:    F: Fn(DownloadProgress) + Send + Sync + 'static,
611:{
612:    let client = client()?;
613:    let (range_supported, total) = probe_range(&client, &request_info).await?;
614:    let callback = Arc::new(on_progress);
615:    let result = match (range_supported, total) {
616:        (true, Some(total)) => segmented(client, request_info, total, cancel, callback).await,
617:        _ => single(client, request_info, total, cancel, callback).await,
618:    };
619:    match result {
620:        Ok(path) => Ok(Some(path)),
621:        Err(e) if e == CANCEL_SENTINEL => Ok(None),
622:        Err(e) => Err(e),
623:    }
624:}
