130:fn client(req: &DownloadRequest) -> Result<Client, String> {
131:    let mut h = HeaderMap::new();
132:    h.insert(ACCEPT_ENCODING, HeaderValue::from_static("identity"));
133:    for (name, v) in [(COOKIE, &req.cookie_header), (REFERER, &req.referer)] {
134:        if let Some(v) = v.as_deref().filter(|v| !v.is_empty()) {
