164:fn content_range(r: &Response) -> Option<(u64, u64, Option<u64>)> {
165:    let v = r.headers().get(CONTENT_RANGE)?.to_str().ok()?.strip_prefix("bytes ")?;
166:    let (range, total) = v.split_once('/')?;
167:    let (a, b) = range.split_once('-')?;
168:    Some((a.trim().parse().ok()?, b.trim().parse().ok()?, total.trim().parse().ok()))
