192:async fn single<F: Fn(DownloadProgress)>(
193:    client: &Client,
194:    req: &DownloadRequest,
195:    first: Option<Response>,
196:    cancel: Arc<AtomicBool>,
197:    on_progress: F,
198:) -> Result<Option<PathBuf>, String> {
199:    let (part, dest) = (side(&req.destination, ".part"), &req.destination);
200:    let mut first = first;
201:    let result = retry(|| {
202:        let resp = first.take();
203:        async {
204:            let mut resp = match resp {
205:                Some(r) => r,
206:                None => client.get(&req.url).send().await.map_err(net)?,
207:            };
208:            if !resp.status().is_success() {
209:                return Err(format!("서버가 오류를 응답했습니다 (HTTP {})", resp.status().as_u16()));
210:            }
211:            let total = resp.content_length();
212:            let p = Progress::new(0, total, DownloadMode::Single, &on_progress);
213:            let mut f = File::create(&part).await.map_err(io)?;
214:            let mut got = 0u64;
215:            while let Some(chunk) = resp.chunk().await.map_err(net)? {
216:                if cancel.load(Ordering::SeqCst) {
217:                    return Ok(false);
218:                }
219:                f.write_all(&chunk).await.map_err(io)?;
220:                got += chunk.len() as u64;
221:                p.add(chunk.len() as u64);
222:            }
223:            f.flush().await.map_err(io)?;
224:            if total.is_some_and(|t| t != got) {
225:                return Err("받은 크기가 서버가 알린 크기와 다릅니다".to_string()); // D5
226:            }
227:            p.finish();
228:            Ok(true)
229:        }
230:    })
231:    .await;
232:    match result {
233:        Ok(true) => {
234:            tokio::fs::rename(&part, dest).await.map_err(io)?;
235:            Ok(Some(dest.clone()))
236:        }
237:        r => {
238:            let _ = tokio::fs::remove_file(&part).await; // 이어받기 불가이므로 남기지 않는다
239:            r.map(|_| None)
240:        }
241:    }
242:}
