244:struct Job<F> {
245:    client: Client,
246:    url: String,
247:    part: PathBuf,
248:    map: PathBuf,
249:    total: u64,
250:    pending: Vec<u64>, // 아직 못 받은 조각 번호
251:    next: AtomicUsize,
252:    stop: AtomicBool,
253:    cancel: Arc<AtomicBool>,
254:    progress: Progress<F>,
255:}
256:
257:impl<F: Fn(DownloadProgress)> Job<F> {
258:    fn span(&self, i: u64) -> (u64, u64) {
259:        (i * CHUNK, ((i + 1) * CHUNK).min(self.total) - 1)
260:    }
261:
262:    // 조각 하나를 통째로 받아 검증한다. 취소되면 None
263:    async fn fetch(&self, i: u64) -> Result<Option<Vec<u8>>, String> {
264:        let (a, b) = self.span(i);
265:        let want = b - a + 1;
266:        let mut resp = self.client.get(&self.url).header(RANGE, format!("bytes={a}-{b}")).send().await.map_err(net)?;
267:        if resp.status().as_u16() != 206 || content_range(&resp) != Some((a, b, Some(self.total))) {
268:            return Err("서버가 요청한 구간과 다른 구간을 보냈습니다".to_string()); // D5
269:        }
270:        let mut buf = Vec::with_capacity(want as usize);
271:        let mut failed = None;
272:        while failed.is_none() {
273:            match resp.chunk().await {
274:                Ok(Some(chunk)) => {
275:                    if self.cancel.load(Ordering::SeqCst) {
276:                        self.progress.undo(buf.len() as u64);
277:                        return Ok(None);
278:                    }
279:                    self.progress.add(chunk.len() as u64);
280:                    buf.extend_from_slice(&chunk);
281:                    if buf.len() as u64 > want {
282:                        break;
283:                    }
284:                }
285:                Ok(None) => break,
286:                Err(e) => failed = Some(net(e)),
287:            }
288:        }
289:        if failed.is_some() || buf.len() as u64 != want {
290:            self.progress.undo(buf.len() as u64);
291:            return Err(failed.unwrap_or_else(|| "받은 조각의 길이가 맞지 않습니다".to_string())); // D5
292:        }
293:        Ok(Some(buf))
294:    }
