307:    async fn worker(&self) -> Result<(), String> {
308:        loop {
309:            let n = self.next.fetch_add(1, Ordering::SeqCst);
310:            if n >= self.pending.len() || self.stop.load(Ordering::SeqCst) || self.cancel.load(Ordering::SeqCst) {
