312:            }
313:            let i = self.pending[n];
314:            let stored = match retry(|| self.fetch(i)).await {
315:                Ok(Some(data)) => self.store(i, &data).await,
316:                Ok(None) => return Ok(()),
317:                Err(e) => Err(e),
318:            };
319:            if stored.is_err() {
320:                self.stop.store(true, Ordering::SeqCst);
321:                return stored;
322:            }
323:        }
