341:async fn segmented<F: Fn(DownloadProgress) + Send + Sync + 'static>(
342:    client: Client,
343:    req: DownloadRequest,
344:    total: u64,
345:    cancel: Arc<AtomicBool>,
346:    on_progress: F,
347:) -> Result<Option<PathBuf>, String> {
348:    let (part, map) = (side(&req.destination, ".part"), side(&req.destination, ".map"));
349:    let n = total.div_ceil(CHUNK);
350:    let done = load_state(&part, &map, total, n).await?;
351:    let pending: Vec<u64> = (0..n).filter(|&i| done[i as usize] == 0).collect();
352:    let have = total - pending.iter().map(|&i| ((i + 1) * CHUNK).min(total) - i * CHUNK).sum::<u64>();
353:    let job = Arc::new(Job {
354:        client,
355:        url: req.url,
356:        part: part.clone(),
357:        map: map.clone(),
358:        total,
359:        next: AtomicUsize::new(0),
360:        pending,
361:        stop: AtomicBool::new(false),
362:        cancel: cancel.clone(),
363:        progress: Progress::new(have, Some(total), DownloadMode::Segmented, on_progress),
364:    });
365:    job.progress.emit(true);
366:    let workers: Vec<_> = (0..CONNECTIONS.min(job.pending.len()))
367:        .map(|_| {
368:            let job = job.clone();
369:            tokio::spawn(async move { job.worker().await })
370:        })
371:        .collect();
372:    let mut failure = None;
373:    for w in workers {
374:        match w.await {
375:            Ok(Ok(())) => {}
376:            Ok(Err(e)) => failure = failure.or(Some(e)),
377:            Err(e) => failure = failure.or(Some(format!("내부 작업 오류: {e}"))),
378:        }
379:    }
380:    if let Some(e) = failure {
381:        return Err(e);
382:    }
383:    if cancel.load(Ordering::SeqCst) {
384:        return Ok(None);
385:    }
386:    job.progress.finish();
387:    tokio::fs::rename(&part, &req.destination).await.map_err(io)?; // D1: 완성 후에만 나타난다
388:    let _ = tokio::fs::remove_file(&map).await;
389:    Ok(Some(req.destination))
390:}

